  "intro": [
   "โรงเรียนได้รับแจ้งว่าอยู่ในรอบการประเมินคุณภาพภายนอกของ สมศ. ตามกรอบปี 2567–2571 รองฯ มาลีตรวจรายงานการประเมินตนเอง (SAR) ที่ทีมเขียนไว้แล้วพบว่า ตัวเลขร้อยละนักเรียนที่อ่านคล่องสูงกว่าข้อมูลดิบในระบบของโรงเรียนมาก ภาพกิจกรรมบางภาพเป็นของปีก่อน และโครงการที่เขียนว่า \"ดำเนินการต่อเนื่อง\" จริง ๆ หยุดไปแล้ว ครูบางคนบอกว่า \"ทุกโรงก็เขียนแบบนี้\""
  ],
  "realCase": "กฎกระทรวงการประกันคุณภาพการศึกษา พ.ศ. 2561 ข้อ 3 ให้สถานศึกษาประเมินผลและตรวจสอบคุณภาพภายใน และจัดส่งรายงานผลการประเมินตนเองให้หน่วยงานต้นสังกัดทุกปี ข้อ 4 ให้ สมศ. ใช้รายงานนั้นประกอบการประเมินภายนอก (ตัวบท 2561 <a href=\"https://natres.psu.ac.th/qa/doc/Announce_QA/%E0%B8%81%E0%B8%8E%E0%B8%81%E0%B8%A3%E0%B8%B0%E0%B8%97%E0%B8%A3%E0%B8%A7%E0%B8%87%20%E0%B8%81%E0%B8%B2%E0%B8%A3%E0%B8%9B%E0%B8%A3%E0%B8%B0%E0%B8%81%E0%B8%B1%E0%B8%99%E0%B8%84%E0%B8%B8%E0%B8%93%E0%B8%A0%E0%B8%B2%E0%B8%9E%E0%B8%81%E0%B8%B2%E0%B8%A3%E0%B8%A8%E0%B8%B6%E0%B8%81%E0%B8%A9%E0%B8%B2%20%E0%B8%9E.%E0%B8%A8.%202561.PDF\" target=\"_blank\" rel=\"noopener\">กฎกระทรวง</a>) ข่าวที่อ้าง สมศ. (2567) ระบุว่าผู้ประเมินวิเคราะห์ SAR ในระบบ Automated QA ก่อนลงพื้นที่แบบ Onsite Virtual หรือ Hybrid 1–3 วัน ผลระดับ 1–2 ต้องแก้ไขเร่งด่วนภายในหนึ่งปีการศึกษาและมีการประเมินซ้ำภายใน 6 เดือนถึง 1 ปี (<a href=\"https://www.dailynews.co.th/news/3572156/\" target=\"_blank\" rel=\"noopener\">เดลินิวส์ มิ.ย. 2567</a>) และ สมศ. เน้น \"ประเมินเพื่อพัฒนาไม่ใช่ประเมินเพื่อจับผิด\" (<a href=\"https://www.dailynews.co.th/news/3688131/\" target=\"_blank\" rel=\"noopener\">เดลินิวส์ ก.ค. 2567</a>)",
  "ambiguity": "ยังไม่พบหนังสือสั่งการที่กำหนดโทษเฉพาะเรื่อง SAR ที่เขียนเกินจริง ด่านนี้ใช้หลักทั่วไปเรื่องความซื่อสัตย์สุจริตตามมาตรา 84 เป็นเกณฑ์",
