  "areaTh": "บุคคล",
  "difficulty": 4,
  "difficultyTh": "ยากที่สุด",
  "intro": [
   "ต้นปีการศึกษา ผู้อำนวยการลงนามคำสั่งแบ่งงานตามที่รองฯ ประเสริฐเสนอ ครูวิไลได้สอน 22 คาบ เป็นครูประจำชั้น หัวหน้างานวัดผล และเวรประจำวันสองวัน ขณะที่ครูอีกหลายคนในกลุ่มสาระมีงานน้อยกว่าชัดเจน ครูวิไลบอกเพื่อนครูว่า \"ถูกกลั่นแกล้งเพราะเคยค้านรองฯ ในที่ประชุม\" และขอพบผู้อำนวยการ หากไม่ได้คำตอบจะยื่นร้องทุกข์"
  ],
  "realCase": "กฎ ก.ค.ศ. ว่าด้วยการร้องทุกข์และการพิจารณาร้องทุกข์ พ.ศ. 2551 (ตัวบท ราชกิจจานุเบกษา 2551 <a href=\"https://otepc.go.th/images/00_YEAR2566/05_PK/%E0%B8%81%E0%B8%8E_%E0%B8%81.%E0%B8%84.%E0%B8%A8._%E0%B8%A7%E0%B9%88%E0%B8%B2%E0%B8%94%E0%B9%89%E0%B8%A7%E0%B8%A2%E0%B8%81%E0%B8%B2%E0%B8%A3%E0%B8%A3%E0%B9%89%E0%B8%AD%E0%B8%87%E0%B8%97%E0%B8%B8%E0%B8%81%E0%B8%82%E0%B9%8C%E0%B9%81%E0%B8%A5%E0%B8%B0%E0%B8%81%E0%B8%B2%E0%B8%A3%E0%B8%9E%E0%B8%B4%E0%B8%88%E0%B8%B2%E0%B8%A3%E0%B8%93%E0%B8%B2%E0%B8%A3%E0%B9%89%E0%B8%AD%E0%B8%87%E0%B8%97%E0%B8%B8%E0%B8%81%E0%B8%82%E0%B9%8C_%E0%B8%9E.%E0%B8%A8._2551.pdf\" target=\"_blank\" rel=\"noopener\">กฎ ก.ค.ศ. ร้องทุกข์</a>) ข้อ 3 ให้ร้องทุกข์ได้เมื่อเห็นว่าไม่ได้รับความเป็นธรรมหรือคับข้องใจจากการกระทำของผู้บังคับบัญชา ข้อ 4 ให้ผู้บังคับบัญชาให้โอกาสและรับฟังปัญหาก่อน ข้อ 5 ให้ยื่นเป็นหนังสือภายในสามสิบวันนับแต่วันทราบเรื่อง ข้อ 7 (2) ให้เรื่องที่เกิดจากผู้บังคับบัญชาตั้งแต่ ผอ.เขตฯ ลงมาร้องทุกข์ต่อ อ.ก.ค.ศ. เขตพื้นที่การศึกษา และข้อ 14 ให้เพิกถอนหรือยกเลิกการปฏิบัติที่ไม่ชอบได้ ข่าวปี 2568 รายงานว่า สพฐ. ย้ายผู้อำนวยการโรงเรียนแห่งหนึ่งไปปฏิบัติงานที่ส่วนกลางหลังครูร้องเรียนพฤติกรรม เพื่อคุ้มครองครูและพยาน (<a href=\"https://www.bangkokbiznews.com/news/news-update/1171745\" target=\"_blank\" rel=\"noopener\">กรุงเทพธุรกิจ 2568</a>)",
