  "difficultyTh": "ยากที่สุด",
  "intro": [
   "นักเรียนหญิง ม.5 หลายคนพบว่าใบหน้าของตนถูกนำไปตัดต่อเป็นภาพและคลิปอนาจาร ส่งต่อกันในกลุ่มแชตของนักเรียน ผู้ต้องสงสัยเป็นนักเรียนชายร่วมชั้นที่บอกว่า \"แค่ล้อเล่น\" ผู้ปกครองของผู้เสียหายรวมตัวกันเรียกร้องให้โรงเรียนไล่ออกทันที ภาพบางส่วนเริ่มหลุดไปนอกโรงเรียน และกลุ่มไลน์ผู้ปกครองเริ่มถามว่าเป็นใคร"
  ],
  "realCase": "ข่าว MGR Online ปี 2568 รายงานกรณีนักเรียนหญิงกว่า 20 คนในโรงเรียนแห่งหนึ่งถูกนักเรียนชายนำใบหน้าไปตัดต่อเป็นภาพและคลิปอนาจาร ผู้ปกครองแจ้งความที่กองบัญชาการตำรวจสืบสวนสอบสวนอาชญากรรมทางเทคโนโลยี ตำรวจระบุว่าผู้ต้องสงสัยเป็นเยาวชน การสอบสวนต้องมีทีมสหวิชาชีพ (<a href=\"https://mgronline.com/crime/detail/9680000052842\" target=\"_blank\" rel=\"noopener\">ข่าว 2568</a>) ศธ. เปิดศูนย์ MOE Safety Center ปี 2565 รับแจ้งเหตุความไม่ปลอดภัยในสถานศึกษา 4 ช่องทาง (<a href=\"https://www.thaipost.net/all-news/82638/\" target=\"_blank\" rel=\"noopener\">ข่าว 2565</a>) อัยการอ้าง พ.ร.บ.คุ้มครองเด็ก พ.ศ. 2546 มาตรา 27 ห้ามเผยแพร่ข้อมูลเกี่ยวกับตัวเด็กโดยเจตนาทำให้เสียชื่อเสียง โทษตามมาตรา 79 จำคุกไม่เกิน 6 เดือน หรือปรับไม่เกิน 60,000 บาท หรือทั้งจำทั้งปรับ (<a href=\"https://www.thaipost.net/main/detail/116684\" target=\"_blank\" rel=\"noopener\">ข่าว 2564</a>) บทความกฎหมายปี 2569 อธิบาย พ.ร.บ.คอมพิวเตอร์ มาตรา 16 เรื่องภาพของผู้อื่นที่ถูกตัดต่อ (<a href=\"https://www.legardy.com/blogs/computer-crime-act-thailand-section-14-16\" target=\"_blank\" rel=\"noopener\">บทความกฎหมาย</a>)",
