  "difficulty": 4,
  "difficultyTh": "ยากที่สุด",
  "intro": [
   "ผู้อำนวยการได้รับคัดเลือกไปอบรมหลักสูตรพัฒนาผู้บริหารแบบเต็มเวลา 3 เดือน ช่วงนั้นมีงานจัดซื้อห้องปฏิบัติการ การอนุมัติให้ครูไปราชการ และหนังสือออกจำนวนมาก โรงเรียนมีรองผู้อำนวยการ 2 คน คือรองฯ ประเสริฐและรองฯ มาลี ครูบางคนถามในกลุ่มไลน์ว่า \"ช่วงนี้ใครเซ็นอะไรได้บ้าง\""
  ],
  "realCase": "บทความที่ยกตัวบท พ.ร.บ.ระเบียบบริหารราชการกระทรวงศึกษาธิการ พ.ศ. 2546 มาตรา 54 ระบุว่าเมื่อไม่มีผู้อำนวยการสถานศึกษาหรือมีแต่ไม่อาจปฏิบัติราชการได้ ให้รองผู้อำนวยการรักษาราชการแทน ถ้ามีรองหลายคน ผู้อำนวยการสำนักงานเขตพื้นที่การศึกษาเป็นผู้แต่งตั้ง (<a href=\"https://www.gotoknow.org/posts/83505\" target=\"_blank\" rel=\"noopener\">บทความ</a>) บทความสรุปมาตรา 45 (6) ว่าผู้อำนวยการสถานศึกษาอาจมอบอำนาจให้ข้าราชการในสถานศึกษา การมอบอำนาจต้องทำเป็นหนังสือ มาตรา 46 ผู้รับมอบอำนาจจะมอบต่อไม่ได้ และมาตรา 47 ผู้มอบต้องกำกับติดตาม (<a href=\"https://www.gotoknow.org/posts/633869\" target=\"_blank\" rel=\"noopener\">บทความ</a>) พ.ร.บ. ฉบับที่ 3 พ.ศ. 2562 (ตัวบท) แก้ไขเฉพาะอนุมาตรา (1) ถึง (3) ของมาตรา 45 และไม่ได้แก้มาตรา 46 (<a href=\"https://legist.mahidol.ac.th/Issues/LoadAttachment/0ecee894-2b2e-47fe-85cb-22a7657d6276\" target=\"_blank\" rel=\"noopener\">พ.ร.บ. ฉบับที่ 3 พ.ศ. 2562</a>) คู่มือของเขตพื้นที่ (เอกสารหน่วยงาน) แยก \"รักษาการในตำแหน่ง\" ตาม พ.ร.บ.ระเบียบข้าราชการครูฯ มาตรา 68 ออกจาก \"รักษาราชการแทน\" ตามมาตรา 53 และ 54 ของ พ.ร.บ. ปี 2546 (<a href=\"https://surat2.go.th/2021/files/com_agency/2022-07_9ea2ea0a2929616.pdf\" target=\"_blank\" rel=\"noopener\">คู่มือเขตพื้นที่</a>)",
  "ambiguity": "ยังไม่ได้เปิดฉบับรวมจากราชกิจจานุเบกษา ข้อความตัวบทมาจากบทความที่ยกมา และยังไม่พบแนววินิจฉัยว่าการไปอบรมเต็มเวลาถือเป็นกรณี \"ไม่อาจปฏิบัติราชการได้\" หรือไม่ รวมถึงยังไม่ได้ตรวจว่าเขตพื้นที่มีคำสั่งมอบอำนาจการแต่งตั้งผู้รักษาราชการแทนให้ผู้อำนวยการสถานศึกษาหรือไม่",
