      "explain": "ประกาศ สพฐ. ปี 2568 กำหนดให้วัดสี่ทักษะ การพูดและเขียนต้องผลิตภาษาจริง ไม่ใช่ปรนัย และการเทียบโอนต้องใช้ผลจาก Proficiency test (<a href=\"https://www.naewna.com/local/915273\" target=\"_blank\" rel=\"noopener\">แนวหน้า</a>)"
