      "explain": "ตรงกับแนวทางที่กระทรวงใช้ คือรายงานความเสียหาย ให้วิศวกรตรวจ และยังไม่เปิดอาคารที่มีแนวโน้มเสียหายรุนแรง (<a href=\"https://www.naewna.com/politic/873505\" target=\"_blank\" rel=\"noopener\">แนวหน้า</a>)"
