  "difficulty": 4,
  "difficultyTh": "ยากที่สุด",
  "intro": [
   "หลังรับนักเรียนเพิ่ม บ้านสวนวิทยามีห้องเรียนเพิ่มขึ้น ข้อมูลอัตรากำลังรายวิชาเอกแสดงว่าสังคมศึกษามีครูเกินเกณฑ์ 2 คน ขณะที่คณิตศาสตร์และวิทยาการคำนวณขาด 3 คน ครูสังคมศึกษาคนหนึ่งจะเกษียณสิ้นปีงบประมาณ เขตพื้นที่แจ้งว่าตำแหน่งว่างของโรงเรียนที่เกินเกณฑ์อาจถูกนำไปใช้ที่โรงเรียนอื่น ครูสังคมศึกษาที่อายุงานน้อยที่สุดเริ่มถามว่าตนจะต้องย้ายหรือไม่ ครูคณิตศาสตร์รับคาบเพิ่มจนครูวิไลบอกว่าไม่ไหวแล้ว"
  ],
  "realCase": "แผนอัตรากำลังของสำนักงานเขตพื้นที่การศึกษาแห่งหนึ่ง ปี 2564 (เอกสารหน่วยงาน) สรุปเกณฑ์ ก.ค.ศ. ว่าโรงเรียนที่มีนักเรียน 120 คนขึ้นไปคำนวณครูจากจำนวนห้องเรียน ชั่วโมงตามหลักสูตร และภาระสอน 20 ชั่วโมงต่อสัปดาห์ ระดับมัธยมคิดห้องละ 35 คน และให้เกลี่ยครูจากโรงเรียนที่เกินเกณฑ์ไปโรงเรียนที่ขาด (<a href=\"https://www.smart.nongkhai2.go.th/wp-content/uploads/2022/07/แผนอัตรากำลัง-2564_merged.pdf\" target=\"_blank\" rel=\"noopener\">แผนอัตรากำลังเขต 2564</a>) ข่าวปี 2565 รายงานว่าการย้ายเพื่อประโยชน์ของทางราชการทำได้ใน 3 กรณี รวมถึงการเกลี่ยอัตรากำลังของสถานศึกษา (<a href=\"https://www.naewna.com/local/669434\" target=\"_blank\" rel=\"noopener\">แนวหน้า 2565</a>) ข่าวปี 2567 สรุปหลักเกณฑ์ ว 6/2567 ว่าสถานศึกษาที่รับย้ายต้องมีอัตรากำลังไม่เกินเกณฑ์ และจำนวนตำแหน่งในวิชาเอกต้องไม่เกินเกณฑ์มาตรฐานวิชาเอก ส่วนการย้ายเพื่อประโยชน์ของทางราชการผ่าน อ.ก.ค.ศ. (<a href=\"https://www.thansettakij.com/economy/618082\" target=\"_blank\" rel=\"noopener\">ฐานเศรษฐกิจ 2567</a>) ข่าวปี 2568 รายงานว่า ก.ค.ศ. ครั้งที่ 8/2568 เห็นชอบตัดโอนตำแหน่งครูที่เกินเกณฑ์ 1,706 อัตราไปเป็นตำแหน่ง 38 ค.(2) ด้านการเงินและพัสดุ (<a href=\"https://www.thaipost.net/public-relations-news/878765/\" target=\"_blank\" rel=\"noopener\">ไทยโพสต์ 2568</a>)",
