  "difficultyTh": "ยากที่สุด",
  "intro": [
   "แผนพัฒนาคุณภาพการศึกษาของบ้านสวนวิทยาฉบับปัจจุบันสิ้นสุดในปีนี้ ผู้อำนวยการต้องจัดทำแผนพัฒนาฉบับใหม่ระยะ 4 ปีและแผนปฏิบัติการประจำปีแรก SAR สามปีย้อนหลังชี้ว่าการอ่าน คิดวิเคราะห์ และเขียน กับผลคณิตศาสตร์ยังต่ำ ห้องน้ำและระบบเครือข่ายต้องซ่อม ขณะที่คำขอโครงการจากทุกกลุ่มงานรวมกันเกินงบที่คาดว่าจะได้รับเกือบสองเท่า"
  ],
  "realCase": "กฎกระทรวงการประกันคุณภาพการศึกษา พ.ศ. 2561 ข้อ 3 (ตัวบท ปี 2561 ราชกิจจานุเบกษา เล่ม 135 ตอนที่ 11 ก) ให้สถานศึกษากำหนดมาตรฐานการศึกษาของสถานศึกษา จัดทำแผนพัฒนาการจัดการศึกษาที่มุ่งคุณภาพ ดำเนินการตามแผน ประเมินผล ติดตาม และจัดส่งรายงานผลการประเมินตนเองให้หน่วยงานต้นสังกัดเป็นประจำทุกปี (<a href=\"https://natres.psu.ac.th/qa/doc/Announce_QA/กฎกระทรวง%20การประกันคุณภาพการศึกษา%20พ.ศ.%202561.PDF\" target=\"_blank\" rel=\"noopener\">กฎกระทรวง QA 2561</a>) ระเบียบ ศธ. ว่าด้วยคณะกรรมการสถานศึกษาขั้นพื้นฐาน พ.ศ. 2543 ให้คณะกรรมการให้ความเห็นชอบแผนปฏิบัติการประจำปีและรายงานผลการดำเนินงานประจำปี (สรุปจากบทความ ปี 2556 ยังต้องตรวจเลขข้อจากตัวบท) (<a href=\"https://www.gotoknow.org/posts/514995\" target=\"_blank\" rel=\"noopener\">สรุประเบียบ 2543</a>) และข่าวปี 2567 ที่เลขาธิการ กพฐ. แจ้งการปรับเงินอุดหนุนค่าจัดการเรียนการสอนแบบขั้นบันไดตามมติ ครม. 26 ก.ค. 2565 (<a href=\"https://www.naewna.com/local/801905\" target=\"_blank\" rel=\"noopener\">แนวหน้า 2567</a>)",
